			t.Fatal("result is nil")
		}
		if len(result) == 0 {
			t.Fatal("result length is 0")
		}
		var v interface{}
		if err := json.Unmarshal(result, &v); err != nil {
			t.Errorf("result is not valid JSON: %v", err)
		}
	})

	t.Run("Invalid format", func(t *testing.T) {
