            Assert.True(ComposeDiff.AreKitDiffsEqual(change.Backward, kitDiffInverted), "GetKitChange: backward diff doesn't match expected inverse diff");

            var appliedForward = ComposeDiff.ApplyKitDiff(kitOriginal, change.Forward);
            Assert.True(ComposeDiff.AreKitsEqual(appliedForward, kitDiffed), "ApplyKitDiff forward: applied kit doesn't match expected diffed kit");

            var appliedInverse = ComposeDiff.ApplyKitDiff(kitDiffed, change.Backward);
            Assert.True(ComposeDiff.AreKitsEqual(appliedInverse, kitOriginal), "ApplyKitDiff inverse: applied inverse kit doesn't match original kit");
        }
