                        Guid = model.Guid,
                        File = new FileId { Guid = model.FileGuid },
                        Tags = model.TagGuids.Select(tagGuid => new TagId { Guid = tagGuid }).ToList(),
                    })
                    .ToList();

                var selected = SelectBestModelLikeComposeTs(models, testCase.SelectedTagGuids);
