    public class GetGeometricInsightsForModel
    {
        static double Round6(double x) => Math.Round(x, 6);
        static object Pt(Point p) => p == null ? null : new { x = Round6(p.X), y = Round6(p.Y), z = Round6(p.Z) };

        [Fact]
