				}
			}
			if qualityGuid == "" {
				t.Fatal("effective floor area quality not found")
			}
			result := SumQualityInDesign(&kit, designGuid, qualityGuid)
			if math.Abs(result-2349.53) > 0.01 {
				t.Errorf("Expected ~2349.53, got %f", result)
			}
		})
	})
}

