			t.Fatalf("result too short for GLB header: got %d bytes", len(result))
		}
		magic := binary.LittleEndian.Uint32(result[0:4])
		if magic != 0x46546C67 {
			t.Errorf("GLB magic number mismatch: got 0x%08X, expected 0x46546C67 (glTF)", magic)
