			}
			for _, k := range []string{"x", "y", "z"} {
				ev, _ := expMap[k].(float64)
				gv, _ := gotMap[k].(float64)
				if math.Abs(gv-ev) > floatTol {
					t.Errorf("mismatch for %s.%s: got %v, expected %v", key, k, gv, ev)
				}
			}
			continue
		}
		if key == "total_surface_area" {
			ev, _ := expected.(float64)
			gv, _ := got.(float64)
			if math.Abs(gv-ev) > floatTol {
				t.Errorf("mismatch for key %s: got %v, expected %v", key, gv, ev)
			}
			continue
		}
		if !reflect.DeepEqual(got, expected) {
			t.Errorf("mismatch for key %s: got %#v, expected %#v", key, got, expected)
		}
	}
}

